Add-Type -AssemblyName 'Microsoft.VisualBasic';
function Test-ComputerName {
	[CmdletBinding()]
	param(
		[string]
		$Value
	);

	if( [string]::IsNullOrWhiteSpace( $Value ) ) {
		return $false;
	}

	if( $Value.Length -gt 15 ) {
		return $false;
	}

	if( $Value -match '\s' ) {
		return $false;
	}

	if( $Value -match '^\d+$' ) {
		return $false;
	}

	if( $Value.IndexOfAny( '{|}~[\]^'':;<=>?@!"#$%`()+/.,*&'.ToCharArray() ) -gt -1 ) {
		return $false;
	}

	return $true;
}
while( $true ) {
	$title = 'Computer name';
	$candidate = [Microsoft.VisualBasic.Interaction]::InputBox( 'Enter a valid computer name:', $title, $candidate );
	if( Test-ComputerName -Value $candidate ) {
		return $candidate;
	} else {
		[Microsoft.VisualBasic.Interaction]::MsgBox( "'${candidate}' is not a valid computer name.", 'Critical, OkOnly', $title ) | Out-Null;
	}
}

$ErrorActionPreference = 'Stop';
Set-StrictMode -Version 'Latest';
& {
	$newName = ( Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\ComputerName.txt' -Raw ).Trim();
	if( [string]::IsNullOrWhitespace( $newName ) ) {
		throw "No computer name was provided.";
	}

	$keys = @(
		@{
			LiteralPath = 'Registry::HKLM\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName';
			Name = 'ComputerName';
		};
		@{
			LiteralPath = 'Registry::HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters';
			Name = 'Hostname';
		};
		@{
			LiteralPath = 'Registry::HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters';
			Name = 'NV Hostname';
		};
	);

	while( $true ) {
		foreach( $key in $keys ) {
			Set-ItemProperty @key -Type 'String' -Value $newName;
		}
		Start-Sleep -Milliseconds 50;
	}
} *>&1 | Out-String -Width 1KB -Stream >> 'C:\Windows\Setup\Scripts\SetComputerName.log';

