# WinUP v3 - computer-wide promotional content policies. # Some policies are not honored on Windows Home/Pro. Do not disable Windows Update. $ErrorActionPreference = 'Continue'
function Set-WinUPDword { param([string]$Path, [string]$Name, [int]$Value) New-Item -Path $Path -Force -ErrorAction Stop | Out-Null New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType DWord -Force -ErrorAction Stop | Out-Null }
$cloud = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' Set-WinUPDword $cloud 'DisableWindowsConsumerFeatures' 1 Set-WinUPDword $cloud 'DisableCloudOptimizedContent' 1 Set-WinUPDword $cloud 'DisableSoftLanding' 1 Set-WinUPDword $cloud 'DisableTailoredExperiencesWithDiagnosticData' 1
# A blank pin policy is a supported-edition-only *enforced* layout and can # restrict user pin customization. Do not silently enforce it on Home/Pro. $edition = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name EditionID -ErrorAction SilentlyContinue).EditionID if ($edition -in @('Enterprise', 'EnterpriseS', 'EnterpriseG', 'Education')) { $explorer = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer' New-Item -Path $explorer -Force | Out-Null New-ItemProperty -Path $explorer -Name 'ConfigureStartPins' -Value '{"pinnedList":[]}' -PropertyType String -Force | Out-Null Write-Output "WinUP: empty Start pin policy configured for edition $edition." } else { Write-Output "WinUP: ConfigureStartPins intentionally skipped for $edition (edition support varies)." }

# WinUP v3 - promotional settings for the default profile or logged-in user. # Run with -RegistryRoot 'Registry::HKEY_USERS\DefaultUser' during specialize, # and with -RegistryRoot 'HKCU:' at first logon. param([string]$RegistryRoot = 'HKCU:') $ErrorActionPreference = 'Continue' function Set-WinUPDword { param([string]$Relative, [string]$Name, [int]$Value) $path = "$RegistryRoot\$Relative" New-Item -Path $path -Force -ErrorAction Stop | Out-Null New-ItemProperty -Path $path -Name $Name -Value $Value -PropertyType DWord -Force -ErrorAction Stop | Out-Null }
$cdm = 'Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager' $names = @( 'ContentDeliveryAllowed', 'FeatureManagementEnabled', 'OEMPreInstalledAppsEnabled', 'PreInstalledAppsEnabled', 'PreInstalledAppsEverEnabled', 'SilentInstalledAppsEnabled', 'SoftLandingEnabled', 'SubscribedContentEnabled', 'SubscribedContent-310093Enabled', 'SubscribedContent-338387Enabled', 'SubscribedContent-338388Enabled', 'SubscribedContent-338389Enabled', 'SubscribedContent-338393Enabled', 'SubscribedContent-353694Enabled', 'SubscribedContent-353696Enabled', 'SubscribedContent-353698Enabled', 'SystemPaneSuggestionsEnabled' ) foreach ($name in $names) { Set-WinUPDword $cdm $name 0 }
# Advertising ID, suggestions, post-update welcome screens, and tips. Set-WinUPDword 'Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 0 Set-WinUPDword 'Software\Microsoft\Windows\CurrentVersion\Privacy' 'TailoredExperiencesWithDiagnosticDataEnabled' 0 Set-WinUPDword 'Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement' 'ScoobeSystemSettingEnabled' 0 Set-WinUPDword 'Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'Start_IrisRecommendations' 0 Set-WinUPDword 'Software\Microsoft\Windows\CurrentVersion\Notifications\Settings\Windows.SystemToast.Suggested' 'Enabled' 0 Write-Output "WinUP: profile promotion settings configured under $RegistryRoot"
